"% margin_03: cascaded (inner + outer) loop robust stability margins
% Inner:  G_in(s) = 1/(s(s+4)), gain ki = 12, unity negative feedback
% Outer:  G_out(s) = 2.5/(s(s+2))
% Total open loop: L(s) = G_out(s) * G_in_cl(s)

s = tf('s');

% --- INNER loop: close first (feedback defaults to negative feedback) ---
G_in    = 1.0 / (s * (s + 4.0));
G_in_cl = feedback(12.0 * G_in, 1);      % ki * G_in / (1 + ki * G_in)

% --- OUTER loop plant/compensator ---
G_out = 2.5 / (s * (s + 2.0));

% --- Cascaded total open loop ---
L = G_out * G_in_cl;

% --- Margins: [Gm, Pm, Wcg, Wcp] = margin(L), assign in raw order ---
[Gm, Pm, Wcg, Wcp] = margin(L);

gm_db  = 20 * log10(Gm);   % linear gain margin -> dB
pm_deg = Pm;               % phase margin, already in degrees
w_gc   = Wcg;              % 3rd output -> w_gc
w_pc   = Wcp;              % 4th output -> w_pc

% --- Write result.json ---
r = struct('gm_db', gm_db, 'pm_deg', pm_deg, 'w_gc', w_gc, 'w_pc', w_pc);
fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(r));
fclose(fid);"
